<?php session_start();$open_connect=1;require('connect.php');$q=trim($_GET['q']??'');$places=[];$shops=[];if($q!==''){$like='%'.$q.'%';$st=mysqli_prepare($connect,"SELECT id_place,place_key,name_place,location_place,image_place FROM place WHERE name_place LIKE ? OR location_place LIKE ? OR description_place LIKE ? OR place_key LIKE ? ORDER BY name_place LIMIT 50");if($st){mysqli_stmt_bind_param($st,'ssss',$like,$like,$like,$like);mysqli_stmt_execute($st);$rs=mysqli_stmt_get_result($st);while($r=mysqli_fetch_assoc($rs))$places[]=$r;mysqli_stmt_close($st);}$st=mysqli_prepare($connect,"SELECT id_shop,name_shop,category_shop,address_shop,description_shop,image_shop FROM shop WHERE status_shop=1 AND (name_shop LIKE ? OR category_shop LIKE ? OR address_shop LIKE ? OR description_shop LIKE ?) ORDER BY name_shop LIMIT 50");if($st){mysqli_stmt_bind_param($st,'ssss',$like,$like,$like,$like);mysqli_stmt_execute($st);$rs=mysqli_stmt_get_result($st);while($r=mysqli_fetch_assoc($rs))$shops[]=$r;mysqli_stmt_close($st);}}?><!doctype html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ค้นหา | TAK EXPLORE</title><link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&family=Prompt:wght@300;400;500;600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#faf9f5;color:#18231e;font-family:Prompt,sans-serif}.container{width:min(1100px,calc(100% - 32px));margin:auto}.nav{height:78px;background:rgba(250,249,245,.96);border-bottom:1px solid #dde2dc;display:flex;align-items:center}.nav .container{display:flex;align-items:center;justify-content:space-between}.logo{font:600 24px 'Playfair Display';color:#183d31;text-decoration:none}.back{color:#68736c;text-decoration:none;font-size:13px}.hero{padding:70px 0 35px}.eyebrow{font-size:10px;letter-spacing:.2em;color:#7d8780;text-transform:uppercase}.hero h1{font:600 clamp(42px,6vw,70px)/1 'Playfair Display';margin:10px 0}.hero p{color:#68736c}.search{display:flex;gap:10px;max-width:760px}.search input{flex:1;border:1px solid #d6ddd7;border-radius:14px;padding:14px;font:400 14px Prompt}.search button{border:0;border-radius:14px;background:#183d31;color:#fff;padding:0 22px;font:600 13px Prompt}.section{padding:30px 0}.section h2{font:600 32px 'Playfair Display'}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:#fff;border:1px solid #e0e4df;border-radius:18px;overflow:hidden}.photo{height:180px;background:center/cover no-repeat}.info{padding:16px}.info h3{font-size:17px;margin:0 0 6px}.info p{font-size:11px;color:#68736c;margin:5px 0;line-height:1.7}.go{display:inline-block;margin-top:10px;padding:8px 12px;border-radius:999px;background:#edf2ec;color:#183d31;font-size:11px;text-decoration:none}.empty{padding:28px;background:#f0f3ed;border-radius:18px;color:#68736c}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.grid{grid-template-columns:1fr}.search{flex-direction:column}.search button{height:44px}}</style></head><body><nav class="nav"><div class="container"><a class="logo" href="home.php">เที่ยว ตาก · TAK EXPLORE</a><a class="back" href="javascript:history.back()">← กลับหน้าก่อน</a></div></nav><main class="container"><section class="hero"><div class="eyebrow">Search Tak Explore</div><h1>ค้นหาสถานที่</h1><p>ค้นหาสถานที่เที่ยว ร้านอาหาร และคาเฟ่ที่คุณอยากไป</p><form class="search" method="get"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="เช่น น้ำตกทีลอซู, แม่สอด, คาเฟ่..." autofocus><button>ค้นหา</button></form></section><?php if($q===''): ?><div class="empty">พิมพ์ชื่อสถานที่ ร้าน หรือคำค้นที่ต้องการได้เลย</div><?php else: ?><section class="section"><h2>สถานที่เที่ยว <small style="font:400 13px Prompt;color:#68736c">(<?=count($places)?> รายการ)</small></h2><?php if($places): ?><div class="grid"><?php foreach($places as $p):$img=explode('|',$p['image_place']??'')[0];?><article class="card" id="place-<?= (int)$p['id_place']?>"><div class="photo" style="background-image:url('<?=htmlspecialchars($img)?>')"></div><div class="info"><h3><?=htmlspecialchars($p['name_place'])?></h3><p>📍 <?=htmlspecialchars($p['location_place'])?></p><a class="go" href="places.php#place-<?= (int)$p['id_place']?>">ดูสถานที่ →</a></div></article><?php endforeach;?></div><?php else:?><div class="empty">ไม่พบสถานที่เที่ยวที่ตรงกับ “<?=htmlspecialchars($q)?>”</div><?php endif;?></section><section class="section"><h2>ร้านอาหาร & คาเฟ่ <small style="font:400 13px Prompt;color:#68736c">(<?=count($shops)?> รายการ)</small></h2><?php if($shops):?><div class="grid"><?php foreach($shops as $s):$img=explode('|',$s['image_shop']??'')[0];?><article class="card"><div class="photo" style="background-image:url('<?=htmlspecialchars($img?:'images/hero-tak.jpeg')?>')"></div><div class="info"><h3><?=htmlspecialchars($s['name_shop'])?></h3><p>📍 <?=htmlspecialchars($s['address_shop']?:'จังหวัดตาก')?> · <?=htmlspecialchars($s['category_shop'])?></p><a class="go" href="shops.php#shop-<?= (int)$s['id_shop']?>">ดูร้าน →</a></div></article><?php endforeach;?></div><?php else:?><div class="empty">ไม่พบร้านอาหารหรือคาเฟ่ที่ตรงกับ “<?=htmlspecialchars($q)?>”</div><?php endif;?></section><?php endif;?></main><?php include('global-search.php');?></body></html>